window.STATISTICS_DIAGNOSTIC=[{"id":"diagnostic-01","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Solve 3x+5=20.","options":["x=5","x=3","x=25","x=15"],"answer":0,"explanation":"Subtract 5 and divide by 3."},{"id":"diagnostic-02","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"For 2,4,6, find the mean.","options":["4","3","6","12"],"answer":0,"explanation":"(2+4+6)/3=4."},{"id":"diagnostic-03","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"For 2,4,100, find the median.","options":["4","35.3","2","100"],"answer":0,"explanation":"The ordered middle value is 4."},{"id":"diagnostic-04","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"What is 25% of 80?","options":["20","25","40","60"],"answer":0,"explanation":"0.25×80=20."},{"id":"diagnostic-05","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Convert 0.37 to a percent.","options":["37%","3.7%","0.37%","370%"],"answer":0,"explanation":"Multiply by 100."},{"id":"diagnostic-06","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"If 18 of 60 cases are successes, p̂ is…","options":["0.30","0.18","3.33","0.60"],"answer":0,"explanation":"18/60=0.30."},{"id":"diagnostic-07","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The complement of probability 0.72 is…","options":["0.28","1.72","0.72","0.36"],"answer":0,"explanation":"1−0.72=0.28."},{"id":"diagnostic-08","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"If events are independent with probabilities 0.5 and 0.4, their intersection is…","options":["0.20","0.90","0.10","0.45"],"answer":0,"explanation":"Multiply independent probabilities."},{"id":"diagnostic-09","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A sample statistic describes…","options":["a sample","a population only","a variable name","a graph style"],"answer":0,"explanation":"Statistics summarize samples."},{"id":"diagnostic-10","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A parameter describes…","options":["a population","a sample only","one case","a residual"],"answer":0,"explanation":"Parameters summarize populations."},{"id":"diagnostic-11","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Which variable is categorical?","options":["blood type","height in cm","age in years","temperature"],"answer":0,"explanation":"Blood type consists of categories."},{"id":"diagnostic-12","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Which variable is quantitative?","options":["annual income","eye color","county name","treatment group"],"answer":0,"explanation":"Income is numerical with meaningful arithmetic."},{"id":"diagnostic-13","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A right-skewed distribution usually has…","options":["a long right tail","a long left tail","no variation","two equal peaks"],"answer":0,"explanation":"Skew direction follows the longer tail."},{"id":"diagnostic-14","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Which measure is most resistant to a high outlier?","options":["median","mean","range","standard deviation"],"answer":0,"explanation":"The median depends mainly on order."},{"id":"diagnostic-15","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"IQR equals…","options":["Q3−Q1","Q1+Q3","max−min","mean−median"],"answer":0,"explanation":"IQR is the width of the middle 50%."},{"id":"diagnostic-16","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A z-score of −2 means…","options":["two SD below the mean","two units below zero","twice the mean","two SD above the mean"],"answer":0,"explanation":"Negative z is below the mean."},{"id":"diagnostic-17","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Correlation r=0 means…","options":["no linear association","no relationship of any kind","perfect independence","causation is absent"],"answer":0,"explanation":"A nonlinear relationship may still exist."},{"id":"diagnostic-18","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A residual equals…","options":["observed−predicted","predicted−observed","slope/intercept","mean−median"],"answer":0,"explanation":"Residual y−ŷ."},{"id":"diagnostic-19","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Random assignment primarily supports…","options":["causal inference","population generalization","larger sample size","perfect measurement"],"answer":0,"explanation":"It balances confounders across treatment groups."},{"id":"diagnostic-20","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Random sampling primarily supports…","options":["generalization to the target population","causal inference by itself","zero nonresponse","perfect blinding"],"answer":0,"explanation":"Probability sampling supports design-based generalization."},{"id":"diagnostic-21","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Voluntary-response samples often suffer from…","options":["self-selection bias","perfect randomness","blocking","matched pairs"],"answer":0,"explanation":"People choose whether to participate."},{"id":"diagnostic-22","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A placebo helps control…","options":["expectation effects","sampling error only","data entry errors","population size"],"answer":0,"explanation":"It helps isolate treatment effects from expectations."},{"id":"diagnostic-23","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"P(A|B) means…","options":["probability of A given B","probability of A or B","probability of not A","probability of B given A"],"answer":0,"explanation":"Condition on B."},{"id":"diagnostic-24","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Mutually exclusive events with positive probability are…","options":["not independent","always independent","identical","complements only"],"answer":0,"explanation":"Their intersection is zero, not the product."},{"id":"diagnostic-25","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Expected value is…","options":["a probability-weighted average","always an observed outcome","the median only","the maximum"],"answer":0,"explanation":"It is the long-run balance point."},{"id":"diagnostic-26","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"For Binomial(n,p), the mean is…","options":["np","n+p","p/n","n(1−p)"],"answer":0,"explanation":"E(X)=np."},{"id":"diagnostic-27","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The area under a density curve is…","options":["1","0","the mean","the variance"],"answer":0,"explanation":"Total probability is 1."},{"id":"diagnostic-28","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Standard error generally decreases when…","options":["sample size increases","sample size decreases","variability increases","bias increases"],"answer":0,"explanation":"Many SEs scale as 1/√n."},{"id":"diagnostic-29","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"The central limit theorem concerns…","options":["sampling distributions of sums or means","all raw data becoming normal","causation","perfect measurement"],"answer":0,"explanation":"Averages approach normality under broad conditions."},{"id":"diagnostic-30","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A 95% confidence method means…","options":["about 95% of repeated intervals capture the parameter","the parameter changes randomly","95% of data lie in the interval","the null is true with 95% probability"],"answer":0,"explanation":"Confidence is a long-run property of the method."},{"id":"diagnostic-31","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A p-value is computed assuming…","options":["the null model is true","the alternative is true","the sample is the population","the result is causal"],"answer":0,"explanation":"The tail probability is under H0."},{"id":"diagnostic-32","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Type I error means…","options":["rejecting a true null","failing to reject a false null","using a small sample","making a graph"],"answer":0,"explanation":"A false positive decision."},{"id":"diagnostic-33","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Power is the probability of…","options":["rejecting a false null","rejecting a true null","accepting every null","obtaining p=0"],"answer":0,"explanation":"Power=1−β."},{"id":"diagnostic-34","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A statistically significant result may still be…","options":["practically unimportant","proof of causation","free of bias","certain to replicate"],"answer":0,"explanation":"Effect size and context matter."},{"id":"diagnostic-35","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Chi-square methods compare…","options":["observed and expected counts","two means directly","correlations only","medians only"],"answer":0,"explanation":"χ² aggregates count discrepancies."},{"id":"diagnostic-36","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"ANOVA compares…","options":["several means through variation ratios","several medians only","two proportions only","one variance to zero"],"answer":0,"explanation":"F compares between- and within-group variation."},{"id":"diagnostic-37","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A bootstrap sample is drawn…","options":["with replacement from observed cases","without replacement from the population","from a normal table only","from residuals only"],"answer":0,"explanation":"Standard bootstrap resamples observed cases with replacement."},{"id":"diagnostic-38","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A permutation test usually…","options":["reshuffles labels under a null model","changes the observed values arbitrarily","assumes the alternative","eliminates all bias"],"answer":0,"explanation":"It generates a randomization reference distribution."},{"id":"diagnostic-39","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"Posterior distribution is proportional to…","options":["likelihood × prior","p-value × sample size","mean × median","variance ÷ SD"],"answer":0,"explanation":"Bayes rule updates prior by likelihood."},{"id":"diagnostic-40","unit":0,"lesson":"diagnostic","skill":"readiness","prompt":"A reproducible analysis should preserve…","options":["data provenance, code, decisions, and outputs","only the final chart","only the p-value","only a screenshot"],"answer":0,"explanation":"An audit trail supports verification."}];
